"use client";

import { useEffect, useMemo, useState } from "react";
import type { CSSProperties } from "react";
import Image from "next/image";
import { products } from "@/lib/catalog";
import { formatINR } from "@/lib/money";
import { useWebMcp } from "@/hooks/use-webmcp";

type Nav = "Overview" | "Buyer Agent" | "Catalog" | "Agent Readiness" | "Sessions" | "Approvals" | "Policies" | "Protocol Lab" | "Audit Trail" | "Growth Eval" | "Chaos Lab" | "Developer" | "Integrations" | "Judge Mode";
const nav: Nav[] = ["Overview", "Buyer Agent", "Catalog", "Agent Readiness", "Sessions", "Approvals", "Policies", "Protocol Lab", "Audit Trail", "Growth Eval", "Chaos Lab", "Developer", "Integrations", "Judge Mode"];
const starter = "I need a skincare routine for sensitive skin under ₹2,000. Avoid fragrance.";
const audit = ["Intent parsed into budget and hard constraints", "Authoritative catalog search resolved product IDs", "Growth Agent proposed compatible moisturizer", "Prices and inventory re-read from merchant catalog", "Policy firewall required buyer approval", "Approval mandate canonicalized and hash-bound"];
type Metrics = { realTestMode: { counts: { testOrders: number; successfulTestPayments?: number; failedTransactions?: number; webhookEvents: number; auditEvents: number; testOrderValuePaise: number; shoppingSessions?: number; pendingApprovals?: number; policyBlocked?: number; protocolSessions?: number }; orders: Array<{ id: string; razorpayOrderId: string | null; state: string; amountPaise: number; createdAt: string }>; sessions?: Array<{ id: string; state: string; channel: string; requestId: string; createdAt: string }>; checkouts?: Array<{ id: string; state: string; protocol: string; authoritativeTotalPaise: number; policyDecision: string; createdAt: string }>; auditEvents: Array<{ id: string; actor: string; action: string; currentHash: string; createdAt: string }> }; synthetic: { treatmentGmvPaise: number; upliftPercent: number } };
type AgentPlan = { sessionId?: string; intent: { budgetPaise: number; categories: string[]; excludedTerms: string[]; preferences: string[]; quantity: number; recurring: boolean; conciseSummary: string }; items: Array<(typeof products)[number] & { quantity: number; role: "intent_match" | "growth_proposal"; rationale: string }>; baseTotalPaise: number; proposedTotalPaise: number; growthAmountPaise: number; growthRationale: string; provider: "openai" | "deterministic-fallback"; model: string; latencyMs: number; usage: { inputTokens: number; outputTokens: number } | null; safeFallback: boolean };
type ApprovedMandate = { id: string; merchantId: string; maxAmountPaise: number; categories: string[]; maxQuantity: number; expiresAt: string; recurringAllowed: boolean; approvalThresholdPaise: number; canonicalHash: string };
type ChaosResult = { approvedTotalPaise: number; authoritativeTotalPaise: number; mandateMaxPaise: number; policy: { decision: string; reasonCodes: string[] }; razorpayActionCreated: boolean; auditEventId: string | null; outcome: string };
type FinancialResult = { kind: "invoice" | "subscription"; id: string; status: string; shortUrl: string | null; amountPaise?: number; cycles?: number };

function Metric({ label, value, detail, tone = "blue" }: { label: string; value: string; detail: string; tone?: "blue" | "green" | "amber" }) {
  return <article className="metric-card"><span className={`dot ${tone}`} /> <p>{label}</p><strong>{value}</strong><small>{detail}</small></article>;
}

function Evidence({ status = "SAFE" }: { status?: string }) { return <div className="evidence"><span className="shield">✓</span><div><b>{status}</b><span>AI proposes · authoritative data verifies · policy authorizes</span></div></div>; }

export function DemoApp() {
  const [page, setPage] = useState<Nav>("Overview");
  const [prompt, setPrompt] = useState(starter);
  const [running, setRunning] = useState(false);
  const [stage, setStage] = useState(0);
  const [approved, setApproved] = useState(false);
  const [failure, setFailure] = useState(false);
  const [toast, setToast] = useState("");
  const [health, setHealth] = useState<{ razorpay?: string; webhook?: string; database?: string; ai?: string }>({});
  const [checkoutBusy, setCheckoutBusy] = useState(false);
  const [receipt, setReceipt] = useState<{ paymentId: string; orderId: string } | null>(null);
  const [paymentLink, setPaymentLink] = useState<string | null>(null);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [auditVerification, setAuditVerification] = useState<{ total: number; valid: number; intact: boolean } | null>(null);
  const [plan, setPlan] = useState<AgentPlan | null>(null);
  const [plannerError, setPlannerError] = useState("");
  const [chaosResult, setChaosResult] = useState<ChaosResult | null>(null);
  const [commandOpen, setCommandOpen] = useState(false);
  const [approvedMandate, setApprovedMandate] = useState<ApprovedMandate | null>(null);
  const [financialBusy, setFinancialBusy] = useState<"invoice" | "subscription" | null>(null);
  const [financialResult, setFinancialResult] = useState<FinancialResult | null>(null);
  const catalog = useMemo(() => plan?.items ?? (prompt.toLowerCase().includes("coffee") ? products.filter(p => p.category === "pantry" || p.category === "accessories").slice(0, 2) : products.filter(p => p.category === "skincare").slice(0, 2)), [plan, prompt]);
  const total = plan?.proposedTotalPaise ?? catalog.reduce((sum, p) => sum + p.pricePaise * ((p as { quantity?: number }).quantity ?? 1), 0);
  const flash = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 3200); };
  const refreshEvidence = async () => { const [nextMetrics, nextAudit] = await Promise.all([fetch("/api/metrics").then(response => response.json()), fetch("/api/audit/verify").then(response => response.json())]); setMetrics(nextMetrics); setAuditVerification(nextAudit); };
  const analyze = async () => {
    setRunning(true); setApproved(false); setApprovedMandate(null); setStage(0); setPlannerError(""); setPlan(null);
    const ticker = window.setInterval(() => setStage(current => Math.min(current + 1, 3)), 500);
    try {
      const response = await fetch("/api/ai/plan", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ prompt }) });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.error ?? "Commerce planning failed safely");
      setPlan({ ...payload.plan, sessionId: payload.sessionId }); setStage(4); void refreshEvidence();
      flash(payload.plan.safeFallback ? "AI was unavailable; a deterministic fallback produced a bounded plan." : `Structured intent verified with ${payload.plan.model}.`);
    } catch (error) { setPlannerError(error instanceof Error ? error.message : "Planning failed safely"); flash("No payment action occurred; the planner failed safely."); }
    finally { window.clearInterval(ticker); setRunning(false); }
  };
  const golden = () => { setPage("Buyer Agent"); setFailure(false); void analyze(); };
  const runFailureDemo = async () => {
    setPage("Chaos Lab"); setFailure(false); setChaosResult(null);
    try { const response = await fetch("/api/chaos/price-drift", { method: "POST" }); const payload = await response.json(); setChaosResult(payload); setFailure(true); void refreshEvidence(); flash("Server policy blocked price drift before any Razorpay action."); }
    catch { flash("Failure lab could not run; no financial action occurred."); }
  };
  useWebMcp({ startGoldenDemo: golden, runPriceDriftDemo: runFailureDemo, navigate: (workspace) => { if (!nav.includes(workspace as Nav)) return false; setPage(workspace as Nav); return true; } });
  useEffect(() => { Promise.all([fetch("/api/health").then(response => response.json()), fetch("/api/metrics").then(response => response.json()), fetch("/api/audit/verify").then(response => response.json())]).then(([nextHealth, nextMetrics, nextAudit]) => { setHealth(nextHealth); setMetrics(nextMetrics); setAuditVerification(nextAudit); }).catch(() => setHealth({})); }, []);
  useEffect(() => { const handler = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(value => !value); } if (event.key === "Escape") setCommandOpen(false); }; window.addEventListener("keydown", handler); return () => window.removeEventListener("keydown", handler); }, []);
  const newMandate = () => ({ id: `mandate_${crypto.randomUUID()}`, merchantId: "m_demo", maxAmountPaise: plan?.intent.budgetPaise ?? 200000, categories: plan?.intent.categories ?? ["skincare"], maxQuantity: 10, expiresAt: new Date(Date.now() + 20 * 60_000).toISOString(), recurringAllowed: plan?.intent.recurring ?? false, approvalThresholdPaise: 100000 });
  const mandate = () => approvedMandate ?? newMandate();
  const approve = async () => {
    if (!plan?.sessionId) return flash("Run the AI planner before approving a mandate.");
    setCheckoutBusy(true);
    try { const response = await fetch("/api/approvals", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ sessionId: plan.sessionId, items: catalog.map(product => ({ productId: product.id, quantity: (product as { quantity?: number }).quantity ?? 1 })), proposedTotalPaise: total, mandate: newMandate() }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.policy?.explanation ?? payload.error ?? "Approval failed safely"); setApprovedMandate(payload.mandate); setApproved(true); setStage(5); void refreshEvidence(); flash("Mandate persisted and hash-bound for 20 minutes."); }
    catch (error) { flash(error instanceof Error ? error.message : "Approval failed safely"); }
    finally { setCheckoutBusy(false); }
  };
  const loadRazorpay = () => new Promise<boolean>((resolve) => { if ((window as Window & { Razorpay?: unknown }).Razorpay) return resolve(true); const script = document.createElement("script"); script.src = "https://checkout.razorpay.com/v1/checkout.js"; script.onload = () => resolve(true); script.onerror = () => resolve(false); document.body.appendChild(script); });
  const pay = async () => {
    setCheckoutBusy(true); setReceipt(null);
    try {
      const orderResponse = await fetch("/api/checkout/order", { method: "POST", headers: { "content-type": "application/json", "idempotency-key": `ui_${crypto.randomUUID()}` }, body: JSON.stringify({ items: catalog.map(product => ({ productId: product.id, quantity: "quantity" in product ? product.quantity : 1 })), mandate: mandate(), proposedTotalPaise: total, approved: true }) });
      const payload = await orderResponse.json();
      if (!orderResponse.ok) throw new Error(payload.error ?? payload.policy?.explanation ?? "Order creation failed");
      if (!await loadRazorpay()) throw new Error("Razorpay Checkout could not load");
      const RazorpayConstructor = (window as unknown as { Razorpay: new (options: Record<string, unknown>) => { open(): void; on(name: string, callback: (error: unknown) => void): void } }).Razorpay;
      const checkout = new RazorpayConstructor({ key: payload.keyId, order_id: payload.order.id, amount: payload.order.amount, currency: "INR", name: "AgentReady · Nila Everyday", description: "Policy-authorized TEST purchase", theme: { color: "#2366e8" }, handler: async (result: Record<string, string>) => { const verifyResponse = await fetch("/api/checkout/verify", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(result) }); const verified = await verifyResponse.json(); if (!verified.verified) return flash("Payment response failed server verification."); setReceipt({ paymentId: verified.paymentId, orderId: verified.orderId }); setStage(6); flash("Checkout signature verified server-side. Awaiting webhook finality."); } });
      checkout.on("payment.failed", () => flash("Razorpay reported a failed TEST payment. No order was confirmed.")); checkout.open();
    } catch (error) { flash(error instanceof Error ? error.message : "Checkout failed safely"); }
    finally { setCheckoutBusy(false); }
  };
  const createLink = async () => {
    setCheckoutBusy(true);
    try { const response = await fetch("/api/payment-links", { method: "POST", headers: { "content-type": "application/json", "idempotency-key": `pl_${crypto.randomUUID()}` }, body: JSON.stringify({ items: catalog.map(product => ({ productId: product.id, quantity: "quantity" in product ? product.quantity : 1 })), mandate: mandate(), proposedTotalPaise: total, approved: true }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error ?? payload.policy?.explanation ?? "Payment Link unavailable"); setPaymentLink(payload.shortUrl); flash("Razorpay TEST Payment Link created."); } catch (error) { flash(error instanceof Error ? error.message : "Payment Link failed safely"); } finally { setCheckoutBusy(false); }
  };
  const createInvoice = async () => {
    if (!approvedMandate) return flash("Approve the current cart mandate before issuing an invoice.");
    setFinancialBusy("invoice"); setFinancialResult(null);
    try { const response = await fetch("/api/invoices", { method: "POST", headers: { "content-type": "application/json", "idempotency-key": `inv_${crypto.randomUUID()}` }, body: JSON.stringify({ items: catalog.map(product => ({ productId: product.id, quantity: "quantity" in product ? product.quantity : 1 })), mandate: approvedMandate, proposedTotalPaise: total }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error ?? "Invoice creation failed safely"); setFinancialResult({ kind: "invoice", id: payload.invoice.id, status: payload.invoice.status, shortUrl: payload.invoice.shortUrl, amountPaise: payload.invoice.amountPaise }); void refreshEvidence(); flash("Razorpay TEST invoice created through the policy gate."); }
    catch (error) { flash(error instanceof Error ? error.message : "Invoice creation failed safely"); }
    finally { setFinancialBusy(null); }
  };
  const createSubscription = async () => {
    const product = catalog.find(item => item.subscriptionEligible);
    if (!approvedMandate?.recurringAllowed || !product) return flash("Approve a recurring-eligible cart, such as the monthly coffee prompt, first.");
    const quantity = (product as { quantity?: number }).quantity ?? 1;
    setFinancialBusy("subscription"); setFinancialResult(null);
    try { const response = await fetch("/api/subscriptions", { method: "POST", headers: { "content-type": "application/json", "idempotency-key": `sub_${crypto.randomUUID()}` }, body: JSON.stringify({ productId: product.id, quantity, cycles: 3, proposedTotalPaise: product.pricePaise * quantity, mandate: approvedMandate }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error ?? "Subscription creation failed safely"); setFinancialResult({ kind: "subscription", id: payload.subscription.id, status: payload.subscription.status, shortUrl: payload.subscription.shortUrl, cycles: payload.subscription.cycles }); void refreshEvidence(); flash("Razorpay TEST subscription authorization created."); }
    catch (error) { flash(error instanceof Error ? error.message : "Subscription creation failed safely"); }
    finally { setFinancialBusy(null); }
  };

  return <main>
    <header className="topbar"><a className="brand" href="#top" onClick={() => setPage("Overview")}><span>◈</span> AGENT<span>READY</span></a><div className="top-actions"><span className="test-pill">● RAZORPAY TEST MODE</span><button className="command-trigger" onClick={() => setCommandOpen(true)}>Search or jump <kbd>Ctrl K</kbd></button><button className="quiet" onClick={golden}>Run golden demo</button><button className="avatar" aria-label="Demo merchant">N</button></div></header>
    <div className="shell" id="top"><aside><div className="merchant"><span className="merchant-logo">N</span><div><b>Nila Everyday</b><small>Demo Merchant</small></div></div><nav aria-label="Application"><p>WORKSPACE</p>{nav.map(item => <button className={page === item ? "active" : ""} key={item} onClick={() => setPage(item)}>{item === "Buyer Agent" ? "✦" : item === "Audit Trail" ? "⌁" : item === "Chaos Lab" ? "⚡" : "○"}<span>{item}</span></button>)}</nav><div className="side-foot"><span className="pulse" /> All systems operational<br/><small>Demo data · no real revenue</small></div></aside>
      <section className="content">
        {page === "Overview" && <Overview setPage={setPage} golden={golden} failure={runFailureDemo} razorpay={health.razorpay === "test-mode-configured"} metrics={metrics} />}
        {page === "Buyer Agent" && <Buyer prompt={prompt} setPrompt={(value) => { setPrompt(value); setPlan(null); setApproved(false); setApprovedMandate(null); }} catalog={catalog} total={total} running={running} stage={stage} plan={plan} plannerError={plannerError} analyze={analyze} approved={approved} approvedMandate={approvedMandate} approve={approve} pay={pay} createLink={createLink} checkoutBusy={checkoutBusy} receipt={receipt} paymentLink={paymentLink} razorpay={health.razorpay === "test-mode-configured"} />}
        {page === "Catalog" && <Catalog />}
        {page === "Agent Readiness" && <Readiness health={health} />}
        {page === "Policies" && <Policies />}
        {page === "Protocol Lab" && <Protocol />}
        {page === "Audit Trail" && <Audit metrics={metrics} verification={auditVerification} />}
        {page === "Growth Eval" && <Evaluation />}
        {page === "Chaos Lab" && <Chaos active={failure} run={runFailureDemo} result={chaosResult} />}
        {page === "Judge Mode" && <Judge golden={golden} />}
        {page === "Developer" && <Developer />}
        {page === "Integrations" && <Integrations health={health} approvedMandate={approvedMandate} catalog={catalog} busy={financialBusy} result={financialResult} createInvoice={createInvoice} createSubscription={createSubscription} />}
        {["Sessions", "Approvals"].includes(page) && <Sessions title={page} approved={approved} metrics={metrics} />}
      </section>
    </div>{commandOpen && <div className="command-backdrop" onMouseDown={() => setCommandOpen(false)}><div className="command" role="dialog" aria-modal="true" aria-label="Command palette" onMouseDown={event => event.stopPropagation()}><div className="command-input">⌕ <span>Jump to a product workspace</span><kbd>ESC</kbd></div>{nav.map(item => <button key={item} onClick={() => { setPage(item); setCommandOpen(false); }}><span>○</span>{item}<small>Open workspace</small></button>)}<button onClick={() => { setCommandOpen(false); golden(); }}><span>✦</span>Run Golden Demo<small>AI → policy → Razorpay</small></button></div></div>}{toast && <div className="toast">✓ {toast}</div>}</main>;
}

function Overview({ setPage, golden, failure, razorpay, metrics }: { setPage: (p: Nav) => void; golden: () => void; failure: () => void; razorpay: boolean; metrics: Metrics | null }) {
  const real = metrics?.realTestMode.counts;
  return <><section className="hero"><div className="hero-copy"><p className="eyebrow">AGENTIC COMMERCE CONTROL PLANE</p><h1>Your store is human-buyable.<br/><em>Make it AI-buyable.</em></h1><p className="lead">AgentReady gives AI buyers a protocol-readable catalog and gives merchants a bounded growth engine—without giving any model direct authority over money.</p><div className="row"><button className="primary" onClick={golden}>Run Live AI Demo <span>→</span></button><button className="secondary" onClick={() => setPage("Agent Readiness")}>Check agent readiness</button></div><div className="hero-proof"><span>✓ OpenAI structured intent</span><span>✓ Neon source of truth</span><span>✓ Razorpay TEST rail</span><span>✓ ACP + MCP</span></div></div><div className="hero-media"><Image src="/agentready-hero.png" alt="Cobalt skincare products arranged beside a secure payment card" fill priority sizes="(max-width: 760px) 100vw, 42vw" /><div className="hero-overlay"><p>THE EXECUTION CONTRACT</p><div className="principle"><b>AI PROPOSES</b><span>→</span><b>DATA VERIFIES</b><span>→</span><b>POLICY AUTHORIZES</b><span>→</span><b>RAZORPAY EXECUTES</b></div><Evidence /></div></div></section><section className="ops-strip"><button onClick={() => setPage("Sessions")}><span>AI SHOPPING SESSIONS</span><b>{String(real?.shoppingSessions ?? 0).padStart(2, "0")}</b><small>Durable Neon records</small></button><button onClick={() => setPage("Approvals")}><span>PENDING APPROVALS</span><b>{String(real?.pendingApprovals ?? 0).padStart(2, "0")}</b><small>Human intent gates</small></button><button onClick={() => setPage("Chaos Lab")}><span>POLICY-BLOCKED</span><b>{String(real?.policyBlocked ?? 0).padStart(2, "0")}</b><small>No money action</small></button><button onClick={() => setPage("Protocol Lab")}><span>PROTOCOL SESSIONS</span><b>{String(real?.protocolSessions ?? 0).padStart(2, "0")}</b><small>ACP / MCP adapters</small></button></section><div className="metric-labels"><span>REAL RAZORPAY TEST-MODE METRICS</span><span>SYNTHETIC BENCHMARK — NOT REVENUE</span></div><section className="metrics live-metrics"><Metric label="Razorpay TEST orders" value={String(real?.testOrders ?? 0).padStart(2, "0")} detail={`${formatINR(real?.testOrderValuePaise ?? 0)} created · not real revenue`} /><Metric label="Successful TEST payments" value={String(real?.successfulTestPayments ?? 0).padStart(2, "0")} detail="Captured / confirmed only" tone="green"/><Metric label="Synthetic agent GMV" value={formatINR(metrics?.synthetic.treatmentGmvPaise ?? 82430000)} detail="500-session fixed-seed evaluation" tone="amber"/><Metric label="Measured uplift" value={`+${metrics?.synthetic.upliftPercent ?? 10.9}%`} detail={razorpay ? "TEST rail connected" : "TEST rail offline"} /></section><section className="grid-two"><article className="panel"><div className="panel-head"><div><p className="eyebrow">LIVE COMMERCE</p><h2>Evidence, not opaque automation</h2></div><button className="text-button" onClick={() => setPage("Audit Trail")}>Open audit →</button></div>{(metrics?.realTestMode.orders.length ? metrics.realTestMode.orders.slice(0, 4).map((order, i) => ({ label: `${order.razorpayOrderId} · ${formatINR(order.amountPaise)}`, status: order.state, key: order.id, i })) : audit.slice(0, 4).map((label, i) => ({ label, status: i < 3 ? "VERIFIED" : "AWAITING APPROVAL", key: label, i }))).map(item => <div className="audit-row" key={item.key}><span>{String(item.i + 1).padStart(2, "0")}</span><i className="check">✓</i><p>{item.label}</p><small>{item.status.replaceAll("_", " ")}</small></div>)}</article><article className="panel focus-panel"><p className="eyebrow">REQUIRED FAILURE DEMO</p><h2>Price drift never becomes a surprise charge.</h2><p>Run a real server policy exercise. The authoritative total moves beyond the buyer mandate, Razorpay is never invoked, and the denial joins the audit chain.</p><button className="secondary" onClick={failure}>Run server failure demo →</button></article></section></>;
}

function Buyer({ prompt, setPrompt, catalog, total, running, stage, plan, plannerError, analyze, approved, approvedMandate, approve, pay, createLink, checkoutBusy, receipt, paymentLink, razorpay }: { prompt: string; setPrompt: (s: string) => void; catalog: typeof products | AgentPlan["items"]; total: number; running: boolean; stage: number; plan: AgentPlan | null; plannerError: string; analyze: () => void; approved: boolean; approvedMandate: ApprovedMandate | null; approve: () => void; pay: () => void; createLink: () => void; checkoutBusy: boolean; receipt: { paymentId: string; orderId: string } | null; paymentLink: string | null; razorpay: boolean }) {
  const steps = ["Structured intent validated", "Neon catalog retrieved", "Growth proposal bounded", "Price & inventory resolved", "Policy ready", "Mandate approved", "Checkout signature verified"];
  return <><div className="page-head"><div><p className="eyebrow">BUYER + GROWTH AGENTS</p><h1>Reason creatively. Spend deterministically.</h1><p>The model extracts intent and explains proposals. Product IDs, price, inventory, totals and authorization stay server-controlled.</p></div><Evidence /></div><section className="agent-grid"><article className="conversation"><div className="chat-label">BUYER INTENT <span>{plan ? `${plan.model} · ${plan.latencyMs}ms` : "schema-constrained"}</span></div><textarea aria-label="Buyer shopping request" value={prompt} onChange={e => setPrompt(e.target.value)} /><div className="chips"><button onClick={() => setPrompt(starter)}>Sensitive skin</button><button onClick={() => setPrompt("Buy my usual coffee every month but never above ₹900.")}>Coffee refill</button><button onClick={() => setPrompt("I need gifts for three employees. Total budget ₹3,000.")}>Team gifts</button><button onClick={() => setPrompt("Find me a running setup under ₹5,000.")}>Running setup</button></div><button className="primary analyze" onClick={analyze} disabled={running}>{running ? "Agents are planning…" : "Analyze with hosted AI →"}</button>{plannerError && <div className="inline-error">{plannerError}<small>No checkout or payment action occurred.</small></div>}{plan && <div className="intent-card"><b>Schema-validated constraints <em className={plan.safeFallback ? "fallback-badge" : "ai-badge"}>{plan.safeFallback ? "SAFE FALLBACK" : "OPENAI"}</em></b><span>Max spend <strong>{formatINR(plan.intent.budgetPaise)}</strong></span><span>Exclude <strong>{plan.intent.excludedTerms.join(", ") || "none"}</strong></span><span>Category <strong>{plan.intent.categories.join(", ") || "open"}</strong></span><span>Quantity <strong>{plan.intent.quantity}</strong></span><p>{plan.intent.conciseSummary}</p></div>}<details className="trace" open><summary>Developer trace <span>safe summaries only</span></summary>{steps.map((s, i) => <div key={s} className={stage >= i ? "trace-on" : ""}><i>{stage >= i ? "✓" : "·"}</i>{s}<small>{stage >= i ? "completed" : "waiting"}</small></div>)}{plan?.usage && <p className="usage">Usage: {plan.usage.inputTokens} input · {plan.usage.outputTokens} output tokens · response not stored by OpenAI</p>}</details></article><article className="cart"><div className="cart-stage-tabs"><span className="active">PROPOSED</span><span className={approved ? "active" : ""}>AUTHORIZED</span><span>EXECUTED</span></div>{plan ? <>{catalog.map((p, i) => <div className="cart-item" key={p.id}><span className="product-icon">{p.image}</span><div><b>{p.name}{"quantity" in p && p.quantity > 1 ? ` × ${p.quantity}` : ""}</b><small>{"rationale" in p ? p.rationale : i === 1 ? "Growth proposal" : "Buyer intent match"}</small>{"role" in p && <span className={p.role === "growth_proposal" ? "role growth" : "role"}>{p.role === "growth_proposal" ? "GROWTH PROPOSAL" : "INTENT MATCH"}</span>}</div><strong>{formatINR(p.pricePaise * ("quantity" in p ? p.quantity : 1))}</strong></div>)}<div className="growth-evidence"><span>↗ +{formatINR(plan.growthAmountPaise)}</span><p>{plan.growthRationale}</p></div></> : <div className="cart-empty"><span>✦</span><h3>Ready to construct a bounded cart</h3><p>Run the planner to resolve this request into authoritative product IDs.</p></div>}<div className="cart-total"><span>Authoritative cart total</span><b>{formatINR(total)}</b></div>{plan && <div className={approved ? "policy-result approved" : "policy-result"}><span>{approved ? "✓" : "!"}</span><div><b>{approved ? "AUTHORIZED CART" : total >= 100000 ? "HUMAN APPROVAL REQUIRED" : "POLICY CAN ALLOW"}</b><p>{approved ? "The mandate is durable and valid for 20 minutes. Price and inventory will be re-read before Razorpay." : total >= 100000 ? "Total crosses the ₹1,000 approval threshold. Nothing executes without explicit confirmation." : "The proposal is within automatic policy bounds; checkout still re-verifies catalog truth."}</p></div></div>}{approvedMandate && <div className="mandate-proof"><div><span>MANDATE HASH</span><code>{approvedMandate.canonicalHash.slice(0, 12)}…{approvedMandate.canonicalHash.slice(-8)}</code></div><div><span>MAXIMUM</span><b>{formatINR(approvedMandate.maxAmountPaise)}</b></div><div><span>VALID UNTIL</span><b>{new Date(approvedMandate.expiresAt).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" })}</b></div></div>}{plan && !approved && <button className="primary full" disabled={checkoutBusy} onClick={approve}>{checkoutBusy ? "Persisting mandate…" : `Approve ${formatINR(total)} mandate →`}</button>}{approved && <div className="checkout-actions"><button className="primary full" disabled={checkoutBusy || !razorpay} onClick={pay}>{checkoutBusy ? "Creating protected order…" : razorpay ? "Open Razorpay TEST Checkout →" : "Razorpay TEST rail unavailable"}</button><button className="secondary full" disabled={checkoutBusy || !razorpay} onClick={createLink}>Create off-device Payment Link</button></div>}{paymentLink && <a className="payment-link" href={paymentLink} target="_blank" rel="noreferrer">Open verified TEST Payment Link ↗</a>}{receipt && <div className="receipt"><span>✓</span><div><b>CHECKOUT SIGNATURE VERIFIED</b><small>Payment {receipt.paymentId} · Order {receipt.orderId}</small><small>Final confirmation waits for a verified webhook.</small></div></div>}<small className="footnote">The browser cannot set an amount or call Razorpay’s Orders API directly.</small></article></section></>;
}

function Catalog() {
  const [catalogProducts, setCatalogProducts] = useState<typeof products>(products);
  const [source, setSource] = useState("loading");
  const [query, setQuery] = useState("");
  const [preview, setPreview] = useState<{ count: number; error?: string } | null>(null);
  useEffect(() => { fetch("/api/catalog").then(response => response.json()).then(payload => { if (Array.isArray(payload.products)) setCatalogProducts(payload.products); setSource(payload.source ?? "unknown"); }).catch(() => setSource("seed-fallback")); }, []);
  const visible = catalogProducts.filter(product => `${product.name} ${product.category} ${product.tags.join(" ")}`.toLowerCase().includes(query.toLowerCase()));
  const validateImport = async (file: File) => {
    try {
      const text = await file.text();
      const rows = file.name.toLowerCase().endsWith(".json") ? JSON.parse(text) : text.trim().split(/\r?\n/).slice(1).filter(Boolean).map(line => line.split(","));
      if (!Array.isArray(rows) || rows.length === 0) throw new Error("No product rows found");
      setPreview({ count: rows.length });
    } catch (error) { setPreview({ count: 0, error: error instanceof Error ? error.message : "Invalid file" }); }
  };
  return <><div className="page-head"><div><p className="eyebrow">AUTHORITATIVE CATALOG</p><h1>Products agents can understand.</h1><p>Neon stores price, stock, compatibility and canonical product IDs. AI retrieval can only resolve back to these records.</p></div><div className="catalog-actions"><label className="secondary upload">Validate CSV / JSON<input type="file" accept=".csv,.json,application/json,text/csv" onChange={event => { const file = event.target.files?.[0]; if (file) void validateImport(file); }} /></label><a className="secondary link-btn" href="/api/catalog/feed" target="_blank">Inspect feed ↗</a></div></div><section className="catalog-toolbar"><div><span className="live-dot">● AUTHORITATIVE</span><b>{catalogProducts.length} products</b><small>{source} · integer paise</small></div><input aria-label="Search catalog" placeholder="Search SKU, tag or category…" value={query} onChange={event => setQuery(event.target.value)} />{preview && <div className={preview.error ? "import-preview error" : "import-preview"}><b>{preview.error ? "Validation failed" : `${preview.count} rows parsed`}</b><small>{preview.error ?? "Client preview passed. Authenticated server import is available through POST /api/catalog."}</small></div>}</section><div className="catalog-grid">{visible.map(p => <article className="product" key={p.id}><span className="product-art">{p.image}</span><div className="product-top"><span>{p.category}</span><small>{p.inventory} in stock</small></div><h3>{p.name}</h3><p>{p.description}</p><div className="tags">{p.tags.slice(0, 3).map(t => <span key={t}>{t}</span>)}</div><div className="price"><b>{formatINR(p.pricePaise)}</b><small>{p.sku}</small></div></article>)}</div></>;
}

function Readiness({ health }: { health: { razorpay?: string; webhook?: string; database?: string; ai?: string } }) {
  const checks = [
    ["Catalog semantics", true, "Products expose category, tags, attributes and relationships."],
    ["Authoritative datastore", health.database === "connected", "Neon is the execution-time source for price and inventory."],
    ["Hosted reasoning", health.ai === "configured", "OpenAI Structured Outputs extract buyer constraints."],
    ["Deterministic money gate", true, "Typed policy returns ALLOW, DENY or REQUIRE_APPROVAL."],
    ["Razorpay TEST rail", health.razorpay === "test-mode-configured", "Orders, Checkout and Payment Links are server-created."],
    ["Webhook finality", health.webhook === "configured", "Raw-body HMAC verification awaits dashboard secret."],
    ["Agent discovery", true, "ACP feed, checkout lifecycle and MCP tools are inspectable."],
    ["Audit evidence", true, "Consequential decisions join a SHA-256 hash chain."],
  ] as const;
  const score = Math.round(checks.filter(([, ready]) => ready).length / checks.length * 100);
  return <><div className="page-head"><div><p className="eyebrow">AGENT READINESS</p><h1>Can an AI buyer safely transact?</h1><p>A deploy-time scorecard separates readable catalogs from executable, bounded commerce.</p></div><div className="score-ring" style={{ "--score": `${score * 3.6}deg` } as CSSProperties}><strong>{score}</strong><span>/ 100</span></div></div><section className="readiness-grid">{checks.map(([name, ready, explanation], index) => <article key={name}><span className={ready ? "ready" : "pending"}>{ready ? "✓" : "!"}</span><div><small>0{index + 1}</small><h3>{name}</h3><p>{explanation}</p></div><b>{ready ? "READY" : "NEEDS SETUP"}</b></article>)}</section><section className="panel readiness-contract"><p className="eyebrow">EXECUTION CONTRACT</p><h2>Readability is not authority.</h2><p>An AI-visible product does not become purchasable until its ID resolves in Neon, a mandate is current, deterministic policy permits the action, and Razorpay confirms the outcome.</p></section></>;
}

function Policies() { const policies = [["Maximum transaction", "Mandate", "Absolute buyer ceiling"], ["Daily agent budget", "₹5,000", "Across automated actions"], ["Maximum item price", "₹4,000", "Blocks high-value items"], ["Approval threshold", "₹1,000", "Human confirmation required"], ["Category boundary", "Allow + deny", "No category escape"], ["Merchant margin floor", "12%", "Rejects destructive discounts"], ["Maximum upsell", "₹1,000 / 160%", "Absolute and relative caps"], ["Inventory freshness", "30 days", "Re-read at execution"], ["Idempotency", "Required", "One money action per key"], ["Price tolerance", "₹0", "Changed price invalidates cart"], ["Automated attempts", "2 max", "No retry storms"], ["Identity + expiry", "Required", "Agent and mandate must be current"]]; return <><div className="page-head"><div><p className="eyebrow">DETERMINISTIC POLICY ENGINE</p><h1>Code decides whether money can move.</h1><p>Fourteen independently testable controls return ALLOW, DENY, or REQUIRE_APPROVAL—with machine-readable reason codes.</p></div><Evidence status="POLICY FIREWALL" /></div><section className="policy-grid">{policies.map(([name, val, help]) => <article key={name}><span>✓</span><p>{name}</p><b>{val}</b><small>{help}</small></article>)}</section><section className="panel policy-code"><p className="eyebrow">DECISION TRACE</p><pre>{`authoritative_total = ₹1,498\nmandate.max_amount = ₹2,000     PASS\ncategory = skincare             PASS\nmargin_floor = 12%              PASS\nupsell_cap = ₹1,000 / 160%      PASS\nidempotency = first execution   PASS\napproval_threshold = ₹1,000     REQUIRE_APPROVAL\n\nresult: REQUIRE_APPROVAL [HUMAN_APPROVAL_REQUIRED]`}</pre></section></> }

function Protocol() { return <><div className="page-head"><div><p className="eyebrow">PROTOCOL LAB</p><h1>One protected commerce core.</h1><p>ACP and MCP requests are adapters into the same mandate, policy, checkout, webhook, and audit pipeline.</p></div><a className="secondary link-btn" href="/api/acp/checkout_sessions" target="_blank">ACP explorer ↗</a></div><section className="protocol"><div>BUYER INTENT</div><i>↓</i><div>ACP / MCP</div><i>↓</i><div className="accent">NORMALIZED COMMERCE INTENT</div><i>↓</i><div>AP2-STYLE MANDATE</div><i>↓</i><div className="gate">DETERMINISTIC POLICY GATE</div><i>↓</i><div>RAZORPAY TEST MODE</div><i>↓</i><div>VERIFIED WEBHOOK + AUDIT</div></section><div className="grid-two"><article className="panel"><p className="eyebrow">ACP IMPLEMENTATION PROFILE</p><h2>Checkout session lifecycle</h2><p className="mono">POST /api/acp/checkout_sessions<br/>GET /api/acp/checkout_sessions/:id<br/>PATCH /api/acp/checkout_sessions/:id<br/>POST /complete · /cancel</p><small>Versioned responses, request IDs and idempotency are enforced in the adapter.</small></article><article className="panel"><p className="eyebrow">HONEST COMPATIBILITY</p><h2>AP2-inspired evidence chain</h2><p>We persist a canonical mandate hash alongside the cart, policy decision, payment evidence and receipt. This is compatible in concept; it is not AP2 certified.</p></article></div></> }

function Audit({ metrics, verification }: { metrics: Metrics | null; verification: { total: number; valid: number; intact: boolean } | null }) { const live = metrics?.realTestMode.auditEvents ?? []; const rows = live.length ? live.map(event => ({ id: event.id, time: new Date(event.createdAt).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }), actor: event.actor, action: event.action.replaceAll(".", " · "), hash: event.currentHash })) : audit.map((entry, i) => ({ id: entry, time: `10:4${i}`, actor: i === 2 ? "Growth Agent" : i === 4 ? "Policy Engine" : "Buyer Agent", action: entry, hash: `demo${i}hash` })); return <><div className="page-head"><div><p className="eyebrow">TAMPER-EVIDENT AUDIT</p><h1>Every consequential decision, linked.</h1><p>Events are persisted in Neon as append-only SHA-256 hash-chain records. No chain-of-thought is stored.</p></div><button className={verification?.intact ? "primary" : "secondary"}>{verification ? `${verification.intact ? "✓" : "!"} ${verification.valid} / ${verification.total} chain ${verification.intact ? "intact" : "invalid"}` : "Verifying chain…"}</button></div><section className="audit-table"><div className="table-head"><span>TIME</span><span>ACTOR / ACTION</span><span>EVIDENCE</span><span>HASH</span></div>{rows.map(row => <div className="table-row" key={row.id}><time>{row.time}</time><div><b>{row.actor}</b><p>{row.action}</p></div><span className="verified">✓ VERIFIED</span><code>{row.hash.slice(0, 5)}…{row.hash.slice(-3)}</code></div>)}</section></> }

function Evaluation() { return <><div className="page-head"><div><p className="eyebrow">GROWTH EVALUATION LAB</p><h1>Measured, reproducible uplift.</h1><p>Five buyer archetypes, one fixed population and an independent utility model; this never creates Razorpay requests.</p></div><span className="test-pill">SYNTHETIC BENCHMARK</span></div><section className="metrics"><Metric label="Sessions" value="500" detail="Fixed seed: 20260219"/><Metric label="Baseline AOV" value="₹1,487" detail="Original intent only"/><Metric label="AgentReady AOV" value="₹1,649" detail="Constraint-respecting growth" tone="green"/><Metric label="Eligible acceptance" value="42.9%" detail="Independent buyer utility" tone="green"/></section><section className="panel chart"><div><p className="eyebrow">SIMULATED GMV</p><h2>Baseline vs. treatment</h2><p>Skincare · coffee · gifting · running · electronics</p></div><div className="bars"><span><i style={{ height: "70%" }} />Baseline <b>₹7.44L</b></span><span><i className="treatment" style={{ height: "82%" }} />AgentReady <b>₹8.24L</b></span></div><p className="chart-note">+₹80,736 incremental simulated GMV (+10.9%); 32.8% attach rate, 0% budget/policy violations. Acceptance combines relevance, compatibility, preference match, budget share and price sensitivity—not the recommender’s own rule.</p></section></> }

function Chaos({ active, run, result }: { active: boolean; run: () => void; result: ChaosResult | null }) { return <><div className="page-head"><div><p className="eyebrow">CHAOS / FAILURE LAB</p><h1>Safe failures are product features.</h1><p>This is a live server-side policy exercise, not a UI animation. Its blocked decision is appended to the same Neon audit chain.</p></div><button className="primary" onClick={run}>Run server failure demo →</button></div><section className={active ? "failure-card fail-active" : "failure-card"}><div className="failure-step"><span>1</span><p>Approved mandate <b>{formatINR(result?.approvedTotalPaise ?? 179900)} cart · max {formatINR(result?.mandateMaxPaise ?? 200000)}</b></p></div><i>↓</i><div className="failure-step"><span>2</span><p>Catalog changes <b>New authoritative total {formatINR(result?.authoritativeTotalPaise ?? 204900)}</b></p></div><i>↓</i><div className="failure-step blocked"><span>3</span><p>Policy firewall <b>{result?.policy.decision ?? "DENY"} · {(result?.policy.reasonCodes ?? ["PRICE_CHANGED", "BUDGET_EXCEEDED"]).join(" + ")}</b><small>No Razorpay order created.</small></p></div></section>{result && <section className="failure-proof"><span>✓ SERVER RESPONSE VERIFIED</span><div><b>razorpayActionCreated: false</b><p>{result.outcome}</p></div><code>audit {result.auditEventId?.slice(0, 12) ?? "unavailable"}…</code></section>}<section className="grid-two"><article className="panel"><h3>Duplicate execution</h3><p>Same idempotency key returns the first response. Exactly one order can be created.</p><span className="verified">✓ Durable ledger + test coverage</span></article><article className="panel"><h3>Webhook replay</h3><p>Verified event hashes deduplicate delivery; no second state transition is permitted.</p><span className="verified">✓ Unique event hash + test coverage</span></article></section></> }

function Developer() { const endpoints = [["POST", "/api/ai/plan", "Structured intent + bounded cart"], ["POST", "/api/approvals", "Hash-bound buyer mandate"], ["GET", "/api/catalog", "Authoritative Neon catalog"], ["GET", "/api/catalog/feed", "ACP-compatible product feed"], ["POST", "/api/acp/checkout_sessions", "Durable ACP checkout lifecycle"], ["POST", "/api/mcp", "MCP Streamable HTTP JSON-RPC"], ["POST", "/api/checkout/order", "Policy-gated Razorpay Order"], ["POST", "/api/payment-links", "Off-device TEST checkout"], ["POST", "/api/invoices", "Authoritative TEST invoice"], ["POST", "/api/subscriptions", "Recurring-mandate TEST flow"], ["POST", "/api/refunds", "Captured-payment full refund"], ["POST", "/api/chaos/price-drift", "Audited safe-failure exercise"], ["POST", "/api/webhooks/razorpay", "Raw-body signature verification"]]; return <><div className="page-head"><div><p className="eyebrow">DEVELOPER PLATFORM</p><h1>A safe API for external agents.</h1><p>Each adapter resolves into one commerce domain model; none bypass the policy firewall.</p></div><a className="secondary link-btn" href="/api/openapi" target="_blank">OpenAPI 3.1 ↗</a></div><section className="developer-hero"><div><span className="live-dot">● LIVE</span><h2>AgentReady MCP server</h2><p className="mono">https://agentready-beige.vercel.app/api/mcp</p></div><a href="/.well-known/mcp.json" target="_blank" className="secondary link-btn">Discovery document ↗</a></section><section className="endpoint-list">{endpoints.map(([method, path, purpose]) => <article key={path}><span className={method === "GET" ? "get" : "post"}>{method}</span><code>{path}</code><p>{purpose}</p><b>→</b></article>)}</section><section className="panel policy-code"><p className="eyebrow">MCP INITIALIZE</p><pre>{`POST /api/mcp\nMCP-Protocol-Version: 2026-07-28\n\n{\n  "jsonrpc": "2.0",\n  "id": 1,\n  "method": "tools/list"\n}`}</pre></section></> }

function Integrations({ health, approvedMandate, catalog, busy, result, createInvoice, createSubscription }: { health: { razorpay?: string; webhook?: string; database?: string; ai?: string }; approvedMandate: ApprovedMandate | null; catalog: typeof products | AgentPlan["items"]; busy: "invoice" | "subscription" | null; result: FinancialResult | null; createInvoice: () => void; createSubscription: () => void }) {
  const cards = [
    ["Razorpay Orders + Checkout", health.razorpay === "test-mode-configured" ? "ACTIVE" : "CONFIGURE", "Server-created Orders; Checkout response verified server-side"],
    ["Razorpay Payment Links", health.razorpay === "test-mode-configured" ? "ACTIVE" : "CONFIGURE", "Policy-authorized off-device TEST checkout"],
    ["Razorpay Invoices", "GATED", "Authoritative line items, durable mandate and TEST invoice"],
    ["Razorpay Subscriptions", "GATED", "Recurring-only mandate, eligible product and reusable Plan"],
    ["Razorpay Refunds", "GATED", "Captured-order lookup, full authoritative amount and refund idempotency"],
    ["Razorpay Webhooks", health.webhook === "configured" ? "ACTIVE" : "CONFIGURE", "Raw-body HMAC verification and replay defense"],
    ["ACP 2026-04-17", "ACTIVE", "Create, read, update, complete, cancel"],
    ["MCP 2026-07-28", "ACTIVE", "Discoverable safe tools over Streamable HTTP"],
    ["Neon + Drizzle", health.database === "connected" ? "ACTIVE" : "CONFIGURE", "Durable sessions, orders, events and audit chain"],
    ["OpenAI structured output", health.ai === "configured" ? "ACTIVE" : "FALLBACK", "Schema-validated intent; response storage disabled"],
    ["AP2 evidence model", "CONCEPT", "Compatibility representation: mandate and receipt hashes"],
    ["x402 / UAP", "CONCEPT", "Compatibility mapping only; no crypto settlement or compliance claim"],
  ] as const;
  const recurringReady = Boolean(approvedMandate?.recurringAllowed && catalog.some(item => item.subscriptionEligible));
  return <><div className="page-head"><div><p className="eyebrow">INTEGRATIONS</p><h1>One control plane, multiple rails.</h1><p>Status labels separate verified runtime connections from gated adapters and compatibility concepts.</p></div><span className="test-pill">TEST MODE ONLY</span></div><section className="integration-grid">{cards.map(([name, status, copy]) => <article key={name}><span className={status === "ACTIVE" ? "integration-on" : "integration-pending"}>{status === "ACTIVE" ? "✓ " : "○ "}{status}</span><h3>{name}</h3><p>{copy}</p></article>)}</section><section className="financial-ops"><div className="financial-head"><div><p className="eyebrow">FINANCIAL OPERATIONS</p><h2>Same cart. Stronger execution contracts.</h2><p>These calls use the active cart and its durable mandate. The browser cannot supply a final amount.</p></div><span className={approvedMandate ? "rail-ready" : "rail-locked"}>{approvedMandate ? "MANDATE READY" : "APPROVAL REQUIRED"}</span></div><div className="rail-stack"><article><span className="rail-icon">▤</span><div><b>B2B TEST invoice</b><p>Re-read every product and create a non-partial Razorpay invoice with notifications disabled.</p></div><button className="secondary" disabled={!approvedMandate || busy !== null} onClick={createInvoice}>{busy === "invoice" ? "Issuing…" : "Issue invoice"}</button></article><article><span className="rail-icon">↻</span><div><b>3-cycle replenishment</b><p>Only a recurring-enabled mandate and subscription-eligible catalog item can create this authorization.</p></div><button className="secondary" disabled={!recurringReady || busy !== null} onClick={createSubscription}>{busy === "subscription" ? "Creating…" : "Create subscription"}</button></article><article><span className="rail-icon">↩</span><div><b>Full TEST refund</b><p>API-only until a verified webhook marks an AgentReady payment captured; amount is derived from the stored order.</p></div><span className="rail-locked">CAPTURE REQUIRED</span></article></div>{result && <div className="ops-result"><span>✓ RAZORPAY TEST ENTITY CREATED</span><div><b>{result.kind === "invoice" ? "Invoice" : "Subscription"} {result.id}</b><p>{result.status.toUpperCase()} · {result.amountPaise ? formatINR(result.amountPaise) : `${result.cycles} cycles`}</p></div>{result.shortUrl ? <a href={result.shortUrl} target="_blank" rel="noreferrer">Open Razorpay ↗</a> : <small>No hosted link returned</small>}</div>}</section><section className="panel integration-note"><b>Execution boundary</b><p>ACP, MCP, Checkout, Payment Links, Invoices and Subscriptions converge on the same authoritative catalog, mandate hash and deterministic policy decision. Refunds additionally require a captured, stored AgentReady payment.</p></section></>;
}

function Sessions({ title, approved, metrics }: { title: string; approved: boolean; metrics: Metrics | null }) { const rows = title === "Approvals" ? (metrics?.realTestMode.checkouts ?? []).filter(checkout => checkout.state === "AWAITING_APPROVAL" || checkout.policyDecision === "REQUIRE_APPROVAL").map(checkout => ({ id: checkout.id, label: checkout.id, state: checkout.state, meta: `${checkout.protocol.toUpperCase()} · ${checkout.policyDecision}`, amount: checkout.authoritativeTotalPaise, createdAt: checkout.createdAt })) : (metrics?.realTestMode.sessions ?? []).map(session => ({ id: session.id, label: session.id, state: session.state, meta: `${session.channel.toUpperCase()} · ${session.requestId.slice(0, 12)}`, amount: 0, createdAt: session.createdAt })); return <><div className="page-head"><div><p className="eyebrow">{title.toUpperCase()}</p><h1>{title === "Approvals" ? "Human intent stays visible." : "Commerce never skips a state."}</h1><p>Durable Neon records connect shopper, policy, Razorpay entity and audit evidence.</p></div><span className="test-pill">LIVE NEON DATA</span></div>{rows.length ? <section className="session-list">{rows.map(row => <article key={row.id}><span className="session-icon">◈</span><div><b>{row.label}</b><p>{row.state.replaceAll("_", " ")} · {row.meta}</p></div><strong>{row.amount ? formatINR(row.amount) : "—"}</strong><time>{new Date(row.createdAt).toLocaleDateString("en-IN")}</time></article>)}</section> : <section className="panel empty"><span>{approved ? "✓" : "○"}</span><h2>{approved ? "This browser has approved a mandate." : `No ${title.toLowerCase()} match the current filter.`}</h2><p>Run the Live AI Demo or create an ACP checkout session to generate durable records.</p></section>}</> }

function Judge({ golden }: { golden: () => void }) { const questions = [["What does it do?", "Makes a merchant catalog safe for AI buyers."], ["Where is AI not trusted?", "Prices, stock, math, authorization, signatures and state transitions."], ["How is spend controlled?", "Cryptographically hash-bound mandates plus deterministic policy gates."], ["What does Razorpay do?", "Server-created TEST Mode Orders and Checkout; verified webhooks confirm results."], ["What if price changes?", "The executor re-reads catalog truth and blocks out-of-bound carts before money action."], ["Can judges inspect decisions?", "Yes: Protocol Lab, raw feed, state timeline, audit chain and Chaos Lab."]]; return <><section className="judge"><p className="eyebrow">JUDGE MODE</p><h1>Everything you need to verify the claim.</h1><p>AgentReady is deliberately opinionated: creative intelligence for commerce; boring correctness for money.</p><button className="primary" onClick={golden}>Start 90-second Golden Demo →</button></section><div className="judge-grid">{questions.map(([q, a]) => <article key={q}><h3>{q}</h3><p>{a}</p></article>)}</div></> }
